/* Reviewed content lives in separate data files; game points are educational only. */
const quizCategories=['quran','prophets','history','prayer','ramadan','culture','names','general'],quizLevels=['beginner','intermediate','hard','expert'];
let quizCategory='all',quizLevel=1;
function approvedQuestions(){return typeof SHAMS_QUIZ==='undefined'?[]:SHAMS_QUIZ.filter(q=>q.active===true&&q.reviewed===true&&q.options?.length===4&&Number.isInteger(q.correct)&&q.correct>=0&&q.correct<4)}
function validQuizSession(t){return !!t&&Array.isArray(t.questions)&&t.questions.length>0&&t.questions.length<=10&&t.questions.every(q=>q&&typeof q.id==='string'&&Array.isArray(q.order)&&q.order.length===4&&new Set(q.order).size===4&&q.order.every(n=>Number.isInteger(n)&&n>=0&&n<4))&&Array.isArray(t.answers)&&Number.isInteger(t.index)&&t.index>=0&&t.index<t.questions.length&&Number.isInteger(t.level)&&t.level>=1&&t.level<=4}
function quizStore(){const s=read('shams-quiz',{});return {version:1,unlocked:Math.max(1,Math.min(4,Number(s?.unlocked)||1)),rounds:Array.isArray(s?.rounds)?s.rounds.filter(r=>r&&typeof r.id==='string'&&Array.isArray(r.answers)&&Array.isArray(r.questions)&&r.total>0&&Number.isInteger(r.correct)&&r.correct>=0&&r.correct<=r.total&&quizLevels[r.level-1]&&typeof r.date==='string').slice(-250):[],daily:s?.daily&&typeof s.daily==='object'?s.daily:{},orders:s?.orders&&typeof s.orders==='object'?s.orders:{},session:validQuizSession(s?.session)?s.session:null}}
function quizText(value){return typeof value==='string'?value:value?.[lang()]||value?.az||''}
function quizSource(q){return `<a class="source-link" href="${esc(q.source_url)}" target="_blank" rel="noopener">${ml('source')}: ${esc(q.source_reference)} ↗</a>`}
function startQuiz(category=quizCategory,level=quizLevel,mode='normal'){const s=quizStore();if(level>s.unlocked)return toast(ml('locked'));let pool=approvedQuestions().filter(q=>category==='all'||q.category===category);const wrong=quizMistakes();if(mode==='mistakes'){category='all';pool=approvedQuestions();pool=[...shuffleItems(pool.filter(q=>wrong.includes(q.id))),...shuffleItems(pool.filter(q=>!wrong.includes(q.id)))]}else pool=shuffleItems(pool).sort((a,b)=>Math.abs(a.difficulty-level)-Math.abs(b.difficulty-level));const chosen=shuffleItems(pool.slice(0,10));if(chosen.length<10)return toast(ml('unavailable'));s.session={id:'round-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),category,level,mode,index:0,questions:chosen.map(q=>({id:q.id,order:shuffleItems([0,1,2,3])})),answers:[],startedAt:Date.now()};if(safeWrite('shams-quiz',s)){go('quiz/play');render()}}
function answerQuiz(index){const s=quizStore(),session=s.session;if(!session||session.answers[session.index])return;const entry=session.questions[session.index],q=approvedQuestions().find(q=>q.id===entry.id);if(!q||!entry.order.includes(index))return;session.answers[session.index]={id:q.id,selected:index,correct:index===q.correct};if(safeWrite('shams-quiz',s))render()}
function advanceQuiz(){const s=quizStore(),session=s.session;if(!session||!session.answers[session.index])return;if(session.index<session.questions.length-1){session.index++;if(safeWrite('shams-quiz',s))render();return}if(!s.rounds.some(r=>r.id===session.id)){s.rounds.push({...session,date:key(placeToday()),completedAt:Date.now(),timezone:place().timezone,correct:session.answers.filter(a=>a.correct).length,total:session.questions.length});if(session.mode==='normal')s.unlocked=Math.max(s.unlocked,Math.min(4,session.level+1))}session.finished=true;if(safeWrite('shams-quiz',s)){go('quiz/result');render()}}
function quizMistakes(){const s=quizStore(),latest={},events=[];for(const r of s.rounds)for(const a of r.answers||[])events.push({...a,at:r.completedAt||r.startedAt||Date.parse(r.date)||0});for(const d of Object.values(s.daily))if(d?.id)events.push({...d,at:d.at||Date.parse(d.date)||0});events.sort((a,b)=>a.at-b.at).forEach(a=>{latest[a.id]=a.correct});return Object.keys(latest).filter(id=>latest[id]===false)}
function learningStreak(){const days=new Set(quizStore().rounds.map(r=>r.date));for(const d of Object.values(quizStore().daily))if(d?.date)days.add(d.date);const date=placeToday();if(!days.has(key(date)))date.setDate(date.getDate()-1);let streak=0;while(days.has(key(date))){streak++;date.setDate(date.getDate()-1)}return streak}
function quizTotals(){const s=quizStore(),answers=s.rounds.flatMap(r=>r.answers||[]).concat(Object.values(s.daily).filter(d=>d?.id));return {correct:answers.filter(a=>a.correct).length,total:answers.length,rounds:s.rounds.length,perfect:s.rounds.some(r=>r.correct===10),categories:new Set(s.rounds.map(r=>r.category==='all'?(r.questions||[]).map(q=>approvedQuestions().find(p=>p.id===q.id)?.category):[r.category]).flat().filter(Boolean)).size}}
function quizHome(){const s=quizStore(),stats=quizTotals();return head(ux('quiz'),'')+`<p class="module-subtitle">${ml('pointsNote')}</p><div class="learning-metrics"><span><b>${stats.correct}</b>${ml('correct')}</span><span><b>${stats.total?Math.round(stats.correct/stats.total*100):0}%</b>${ml('accuracy')}</span><span><b>${stats.rounds}</b>${ml('round')}</span></div>${s.session&&!s.session.finished?`<button class="goldbtn wide" onclick="go('quiz/play')">${ml('resume')} →</button>`:''}<section class="card game-setup"><label class="field-label">${ml('level')}<select aria-label="${ml('level')}" onchange="quizLevel=Number(this.value)">${quizLevels.map((l,i)=>`<option value="${i+1}" ${i+1>s.unlocked?'disabled':''} ${quizLevel===i+1?'selected':''}>${ml(l)} ${i+1>s.unlocked?'· 🔒':''}</option>`).join('')}</select></label><label class="field-label">${ml('category')}<select aria-label="${ml('category')}" onchange="quizCategory=this.value"><option value="all">${ml('all')}</option>${quizCategories.map(c=>`<option value="${c}" ${quizCategory===c?'selected':''}>${ml(c)}</option>`).join('')}</select></label><button class="goldbtn wide" onclick="startQuiz()">${ml('start')} · 10 →</button></section><div class="module-menu">${[['daily','☀','dailyQuestion'],['results','▥','results'],['achievements','✦','achievements'],['mistakes','↶','mistakes']].map(([r,i,k])=>`<button onclick="go('quiz/${r}')"><i>${i}</i><span>${ml(k)}</span><b>›</b></button>`).join('')}</div>`}
function quizPlay(){const session=quizStore().session;if(!session||session.finished)return quizHome();const entry=session.questions[session.index],q=approvedQuestions().find(q=>q.id===entry?.id);if(!q)return `<p>${ml('unavailable')}</p><button class="goldbtn" onclick="go('quiz')">${ml('home')}</button>`;const a=session.answers[session.index];return head(ux('quiz'),'')+`<div class="question-counter"><span>${session.index+1} / ${session.questions.length}</span><span>${Math.round(session.answers.length/session.questions.length*100)}%</span></div><div class="progress"><div style="width:${session.answers.length/session.questions.length*100}%"></div></div><article class="question-card"><small>${ml(q.category)} · ${ml(quizLevels[session.level-1])}</small><h2>${esc(quizText(q.question))}</h2><div class="answer-options">${entry.order.map((original,i)=>`<button class="${a?(original===q.correct?'correct':original===a.selected?'incorrect':''):''}" ${a?'disabled':''} onclick="answerQuiz(${original})"><b>${'ABCD'[i]}</b><span>${esc(quizText(q.options[original]))}</span><i>${a&&original===q.correct?'✓':a&&original===a.selected?'×':''}</i></button>`).join('')}</div>${a?`<section class="answer-explanation"><strong>${ml(a.correct?'correct':'wrong')}</strong><p>${esc(quizText(q.explanation))}</p>${quizSource(q)}</section><button class="goldbtn wide" onclick="advanceQuiz()">${ml(session.index===session.questions.length-1?'finish':'next')} →</button>`:''}</article>`}
function quizResult(){const s=quizStore(),r=s.rounds.find(r=>r.id===s.session?.id)||s.rounds.at(-1);if(!r)return quizHome();return head(ml('results'),'')+`<section class="card result-card"><span>✦</span><strong>${r.correct*10}<small> / ${r.total*10}</small></strong><p>${ml('score')}</p><div class="learning-metrics"><span><b>${r.correct}</b>${ml('correct')}</span><span><b>${r.total-r.correct}</b>${ml('wrong')}</span><span><b>${Math.round(r.correct/r.total*100)}%</b>${ml('accuracy')}</span></div><p class="notice">${ml('pointsNote')}</p><div class="module-actions"><button class="goldbtn" onclick="startQuiz('${r.category}',${r.level})">${ml('again')}</button><button class="secondarybtn" onclick="go('quiz')">${ml('home')}</button></div></section><div class="quiz-review">${(r.answers||[]).map(a=>{const q=approvedQuestions().find(q=>q.id===a.id);return q?`<details><summary><span class="${a.correct?'good':'bad'}">${a.correct?'✓':'×'}</span>${esc(quizText(q.question))}</summary><p>${esc(quizText(q.options[q.correct]))}</p><p class="muted">${esc(quizText(q.explanation))}</p>${quizSource(q)}</details>`:''}).join('')}</div>`}
function quizAchievements(){const t=quizTotals(),items=[['ach10',t.correct>=10],['ach50',t.correct>=50],['ach100',t.correct>=100],['perfect',t.perfect],['streak',learningStreak()>=7],['allCategories',t.categories===8]];return head(ml('achievements'),'')+`<div class="achievement-list">${items.map(([k,on])=>`<article class="card ${on?'earned':''}"><span>${on?'✦':'◇'}</span><strong>${ml(k)}</strong><b>${on?'✓':'○'}</b></article>`).join('')}</div><p class="notice">${ml('pointsNote')}</p>`}
function quizHistory(){const rows=quizStore().rounds;return head(ml('results'),'')+(rows.length?`<div class="quiz-review">${rows.slice().reverse().map(r=>`<details><summary>${r.date} · ${r.correct*10} / ${r.total*10} · ${ml(quizLevels[r.level-1]||'beginner')}</summary><p>${ml('correct')}: ${r.correct} · ${ml('wrong')}: ${r.total-r.correct}</p><p>${ml('category')}: ${ml(r.category)}</p></details>`).join('')}</div>`:`<div class="module-empty">▥<p>${ml('empty')}</p></div>`)}
function quizWrong(){const ids=quizMistakes(),list=approvedQuestions().filter(q=>ids.includes(q.id));return head(ml('mistakes'),'')+(list.length?`<button class="goldbtn wide" onclick="startQuiz('all',1,'mistakes')">${ml('review')} →</button><div class="quiz-review">${list.map(q=>`<details><summary>${esc(quizText(q.question))}</summary><p>${esc(quizText(q.options[q.correct]))}</p><p class="muted">${esc(quizText(q.explanation))}</p>${quizSource(q)}</details>`).join('')}</div>`:`<div class="module-empty">✧<p>${ml('empty')}</p></div>`)}
function dailyQuizKey(){return (place().timezone||'local')+'|'+key(placeToday())}
function dailyQuestion(){const pool=approvedQuestions(),d=placeToday(),n=Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000);return pool[n%pool.length]}
function answerDailyQuiz(index){const s=quizStore(),k=dailyQuizKey(),q=dailyQuestion();if(!q||s.daily[k]||!Number.isInteger(index)||index<0||index>3)return;s.daily[k]={id:q.id,selected:index,correct:index===q.correct,date:key(placeToday()),at:Date.now()};if(safeWrite('shams-quiz',s))render()}
function dailyQuizPage(){const q=dailyQuestion();if(!q)return quizHome();const s=quizStore(),k=dailyQuizKey(),a=s.daily[k];if(!Array.isArray(s.orders[k])){s.orders[k]=shuffleItems([0,1,2,3]);safeWrite('shams-quiz',s)}const order=s.orders[k];return head(ml('dailyQuestion'),'')+`<p class="module-subtitle">${localizedDate(placeToday())} · ${esc(place().timezone)}<br>${ml('dailyNote')}</p><article class="question-card"><h2>${esc(quizText(q.question))}</h2><div class="answer-options">${order.map((n,i)=>`<button ${a?'disabled':''} class="${a?(n===q.correct?'correct':n===a.selected?'incorrect':''):''}" onclick="answerDailyQuiz(${n})"><b>${'ABCD'[i]}</b><span>${esc(quizText(q.options[n]))}</span></button>`).join('')}</div>${a?`<section class="answer-explanation"><strong>${ml(a.correct?'correct':'wrong')}</strong><p>${esc(quizText(q.explanation))}</p>${quizSource(q)}</section>`:''}</article>`}
function quizPage(){if(!approvedQuestions().length)return modWrap(head(ux('quiz'),'')+`<p>${ml('unavailable')}</p>`);const mode=location.hash.split('/')[1]||'';return modWrap(({play:quizPlay,result:quizResult,results:quizHistory,achievements:quizAchievements,mistakes:quizWrong,daily:dailyQuizPage}[mode]||quizHome)())}
/* Asma: manual learning state, repeat deck and independent practice results. */
let namesQuery='',namesFilter='all',namesPageIndex=0,flashIndex=0,flashFlipped=false;
function allNames(){return typeof SHAMS_NAMES==='undefined'?[]:SHAMS_NAMES.filter(n=>n.reviewed&&n.id>=1&&n.id<=99)}
function validNamesTest(t){return !!t&&['meaning','name'].includes(t.mode)&&Array.isArray(t.questions)&&t.questions.length>0&&t.questions.length<=10&&Array.isArray(t.answers)&&Number.isInteger(t.index)&&t.index>=0&&t.index<t.questions.length&&t.questions.every(q=>q&&Number.isInteger(q.id)&&q.id>=1&&q.id<=99&&Array.isArray(q.choices)&&q.choices.length===4&&new Set(q.choices).size===4&&q.choices.every(n=>Number.isInteger(n)&&n>=1&&n<=99))}
function namesStore(){const s=read('shams-names',{}),ids=new Set(allNames().map(n=>n.id)),clean=a=>Array.isArray(a)?[...new Set(a.map(Number).filter(n=>ids.has(n)))]:[];return {version:1,learned:clean(s?.learned),favorites:clean(s?.favorites),review:clean(s?.review),plan:[3,5,10].includes(Number(s?.plan))?Number(s.plan):5,daily:s?.daily&&typeof s.daily==='object'?s.daily:{},attempts:Array.isArray(s?.attempts)?s.attempts.filter(a=>a&&a.total>0&&Number.isFinite(a.correct)).slice(-100):[],test:validNamesTest(s?.test)?s.test:null}}
function nameMeaning(n){return n.meaning[lang()]||n.meaning.az}
function nameExplain(n){return n.explanation[lang()]||n.explanation.az}
function namesSourceNote(){return typeof SHAMS_NAMES_SOURCE!=='undefined'?quizText(SHAMS_NAMES_SOURCE.note):''}
function updateNameState(id,field){const s=namesStore(),at=s[field].indexOf(Number(id));if(at<0)s[field].push(Number(id));else s[field].splice(at,1);if(safeWrite('shams-names',s))render()}
function namePlan(){const s=namesStore(),today=key(placeToday()),saved=s.daily[today];if(saved&&saved.plan===s.plan&&Array.isArray(saved.ids))return saved.ids;const ordered=[...s.review,...allNames().map(n=>n.id).filter(id=>!s.learned.includes(id))],ids=[...new Set(ordered)].slice(0,s.plan);if(!ids.length)ids.push(...allNames().slice(0,s.plan).map(n=>n.id));s.daily[today]={plan:s.plan,ids};safeWrite('shams-names',s);return ids}
function setNamePlan(n){const s=namesStore();s.plan=[3,5,10].includes(Number(n))?Number(n):5;delete s.daily[key(placeToday())];if(safeWrite('shams-names',s)){flashIndex=0;render()}}
function namesResults(){const s=namesStore(),q=normalizeSearch(namesQuery),list=allNames().filter(n=>(namesFilter!=='favorites'||s.favorites.includes(n.id))&&(namesFilter!=='learned'||s.learned.includes(n.id))&&normalizeSearch(n.arabic+' '+n.latin+' '+nameMeaning(n)+' '+n.id).includes(q)),size=Math.max(3,Math.min(9,Math.floor(((window.innerHeight||740)-465)/64))),pages=Math.max(1,Math.ceil(list.length/size));namesPageIndex=Math.max(0,Math.min(namesPageIndex,pages-1));return list.length?`<div class="asma-list">${list.slice(namesPageIndex*size,(namesPageIndex+1)*size).map(n=>`<button onclick="go('asma/${n.id}')"><small>${n.id}</small><span><strong>${esc(n.latin)}</strong><em>${esc(nameMeaning(n))}</em></span><b class="arabic" lang="ar" dir="rtl">${n.arabic}</b><i>${s.learned.includes(n.id)?'✓':s.favorites.includes(n.id)?'♥':'›'}</i></button>`).join('')}</div>`+pageLinks(namesPageIndex,pages,'setNamesPage'):`<div class="module-empty">✧<p>${ml('empty')}</p></div>`}
function setNamesPage(n){namesPageIndex=n;document.querySelector('#namesResults').innerHTML=namesResults()}
function searchNames(q){namesQuery=q;namesPageIndex=0;document.querySelector('#namesResults').innerHTML=namesResults()}
function setNamesFilter(f){namesFilter=f;namesPageIndex=0;render()}
function asmaHome(){const s=namesStore();return head(ux('names'),'')+`<div class="learning-metrics"><span><b>${s.learned.length}</b>${ml('learned')}</span><span><b>${99-s.learned.length}</b>${ml('remaining')}</span><span><b>${Math.round(s.learned.length/99*100)}%</b>${ml('completion')}</span></div><div class="module-menu two-columns"><button onclick="go('asma/cards')"><i>▱</i><span>${ml('memorize')}</span></button><button onclick="go('asma/test')"><i>✦</i><span>${ml('test')}</span></button></div><div class="module-toolbar"><input type="search" aria-label="${ml('search')}" placeholder="${ml('search')}" value="${esc(namesQuery)}" oninput="searchNames(this.value)"></div><div class="chip-tabs" data-swipe-lock="true">${['all','favorites','learned'].map(f=>`<button aria-pressed="${namesFilter===f}" onclick="setNamesFilter('${f}')">${ml(f)}</button>`).join('')}</div><div id="namesResults">${namesResults()}</div><details class="module-help"><summary>${ml('source')}</summary><p>${esc(namesSourceNote())}</p><a class="source-link" href="https://sunnah.com/tirmidhi:3507" target="_blank" rel="noopener">Tirmidhi 3507 ↗</a></details>`}
function nameDetail(id){const n=allNames().find(n=>n.id===id),s=namesStore();if(!n)return asmaHome();const audio=typeof n.audio==='string'&&/^https:\/\//.test(n.audio)?n.audio:null;return head(n.latin,'')+`<article class="card name-detail"><small>${n.id} / 99</small><h2 class="arabic" lang="ar" dir="rtl">${n.arabic}</h2><h3>${esc(n.latin)}</h3><strong>${esc(nameMeaning(n))}</strong><p>${esc(nameExplain(n))}</p>${audio?`<audio controls preload="none" id="nameAudio" src="${esc(audio)}" aria-label="${ml('listen')}"></audio><label class="form-check"><input type="checkbox" onchange="document.querySelector('#nameAudio').loop=this.checked">${ml('repeat')}</label>`:`<button class="secondarybtn" disabled>▷ ${ml('listen')}</button><p class="notice">${ml('audioMissing')}</p>`}<div class="module-actions"><button class="secondarybtn" aria-pressed="${s.favorites.includes(id)}" onclick="updateNameState(${id},'favorites')">${s.favorites.includes(id)?'♥':'♡'} ${ml(s.favorites.includes(id)?'unfavorite':'favorite')}</button><button class="goldbtn" aria-pressed="${s.learned.includes(id)}" onclick="updateNameState(${id},'learned')">${ml(s.learned.includes(id)?'unlearn':'markLearned')}</button></div><p class="notice">Tirmidhi 3507</p><a class="source-link" href="${esc(n.source_url)}" target="_blank" rel="noopener">${ml('source')} ↗</a></article><div class="quran-pagination"><button class="secondarybtn" ${id<=1?'disabled':''} onclick="go('asma/${id-1}')">← ${ml('previous')}</button><button class="secondarybtn" ${id>=99?'disabled':''} onclick="go('asma/${id+1}')">${ml('next')} →</button></div><details class="module-help"><summary>${ml('source')}</summary><p>${esc(namesSourceNote())}</p></details>`}
function flashPage(){const s=namesStore(),ids=namePlan();flashIndex=Math.max(0,Math.min(flashIndex,ids.length-1));const n=allNames().find(n=>n.id===ids[flashIndex]);if(!n)return asmaHome();return head(ml('memorize'),'')+`<label class="field-label">${ml('plan')}<select onchange="setNamePlan(this.value)">${[3,5,10].map(p=>`<option value="${p}" ${p===s.plan?'selected':''}>${p} ${ml('perDay')}</option>`).join('')}</select></label><p class="module-subtitle">${ml('todayPlan')} · ${flashIndex+1} / ${ids.length}</p><button class="flash-card ${flashFlipped?'flipped':''}" aria-label="${ml('flip')}" aria-pressed="${flashFlipped}" onclick="flashFlipped=!flashFlipped;render()">${flashFlipped?`<strong>${esc(nameMeaning(n))}</strong><p>${esc(nameExplain(n))}</p>`:`<span class="arabic" lang="ar" dir="rtl">${n.arabic}</span><strong>${esc(n.latin)}</strong>`}<small>↶ ${ml('flip')}</small></button><div class="module-actions"><button class="secondarybtn" onclick="flashIndex=(${flashIndex-1}+${ids.length})%${ids.length};flashFlipped=false;render()">←</button><button class="goldbtn" onclick="updateNameState(${n.id},'learned')">${s.learned.includes(n.id)?'✓ '+ml('learned'):ml('markLearned')}</button><button class="secondarybtn" onclick="flashIndex=(${flashIndex+1})%${ids.length};flashFlipped=false;render()">→</button></div><p class="notice">${ml('reviewDue')}: ${s.review.length}</p>`}
function makeNameQuestion(id,mode){const n=allNames().find(n=>n.id===id),meaning=normalizeSearch(nameMeaning(n)),seen=new Set([meaning]),others=shuffleItems(allNames().filter(x=>x.id!==id)).filter(x=>{const k=normalizeSearch(nameMeaning(x));if(seen.has(k))return false;seen.add(k);return true}).slice(0,3);return {id,choices:shuffleItems([id,...others.map(x=>x.id)]),mode}}
function startNameTest(mode){const s=namesStore(),pool=shuffleItems(allNames()).slice(0,10);s.test={id:'names-'+Date.now(),mode,index:0,questions:pool.map(n=>makeNameQuestion(n.id,mode)),answers:[],finished:false};if(safeWrite('shams-names',s))render()}
function answerNameTest(id){const s=namesStore(),t=s.test;if(!t||t.finished||t.answers[t.index])return;const q=t.questions[t.index];if(!q.choices.includes(id))return;t.answers[t.index]={id:q.id,selected:id,correct:id===q.id};if(id===q.id)s.review=s.review.filter(x=>x!==q.id);else if(!s.review.includes(q.id))s.review.push(q.id);if(safeWrite('shams-names',s))render()}
function nextNameTest(){const s=namesStore(),t=s.test;if(!t||!t.answers[t.index])return;if(t.index<t.questions.length-1)t.index++;else{t.finished=true;if(!s.attempts.some(a=>a.id===t.id))s.attempts.push({id:t.id,date:key(placeToday()),correct:t.answers.filter(a=>a.correct).length,total:t.questions.length,mode:t.mode})}if(safeWrite('shams-names',s))render()}
function namesTestPage(){const s=namesStore(),t=s.test;if(!t||t.finished)return head(ml('test'),'')+`${t?.finished?`<section class="card result-card"><strong>${t.answers.filter(a=>a.correct).length} / ${t.questions.length}</strong><p>${ml('correct')}</p></section>`:''}<div class="module-menu">${[['meaning','findMeaning'],['name','findName']].map(([m,k])=>`<button onclick="startNameTest('${m}')"><i>✦</i><span>${ml(k)}</span><b>›</b></button>`).join('')}<button onclick="go('asma/cards')"><i>▱</i><span>${ml('cards')}</span><b>›</b></button></div><details class="module-help" open><summary>${ml('testResults')}</summary><p>${ml('reviewDue')}: ${s.review.length}</p>${s.attempts.slice().reverse().slice(0,10).map(a=>`<p>${a.date} · ${a.correct} / ${a.total}</p>`).join('')}</details>`;const q=t.questions[t.index],n=allNames().find(n=>n.id===q.id),a=t.answers[t.index];return head(ml(t.mode==='meaning'?'findMeaning':'findName'),'')+`<p class="module-subtitle">${t.index+1} / ${t.questions.length}</p><article class="question-card"><h2 ${t.mode==='meaning'?'class="arabic" lang="ar" dir="rtl"':''}>${t.mode==='meaning'?n.arabic:esc(nameMeaning(n))}</h2><div class="answer-options">${q.choices.map((id,i)=>{const x=allNames().find(n=>n.id===id);return `<button ${a?'disabled':''} class="${a?(id===q.id?'correct':id===a.selected?'incorrect':''):''}" onclick="answerNameTest(${id})"><b>${'ABCD'[i]}</b><span ${t.mode==='name'?'lang="ar" dir="rtl"':''}>${t.mode==='meaning'?esc(nameMeaning(x)):x.arabic}</span></button>`}).join('')}</div>${a?`<section class="answer-explanation"><strong>${ml(a.correct?'correct':'wrong')}</strong><p>${esc(nameExplain(n))}</p><a class="source-link" href="${esc(n.source_url)}" target="_blank" rel="noopener">${esc(n.source_reference)} ↗</a></section><button class="goldbtn wide" onclick="nextNameTest()">${ml(t.index===t.questions.length-1?'finish':'next')}</button>`:''}</article>`}
function asmaPage(){if(!allNames().length)return modWrap(head(ux('names'),'')+`<p>${ml('unavailable')}</p>`);const part=location.hash.split('/')[1]||'';return modWrap(part==='cards'?flashPage():part==='test'?namesTestPage():/^\d+$/.test(part)?nameDetail(Number(part)):asmaHome())}
